"use client";

import React, { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { TiltedCard } from "./TiltedCardBlock";

// ==========================================
// PLATFORM GRID
// Everything a product offers, as one hairline grid: small tiles with an icon
// and a name, and a few 2×2 features that show a piece of the product on a
// tilting card. Tiles pack densely, so the features stay square at every
// column count. The grid reveals once as a wave from its centre, then a
// spotlight follows the pointer across it.
// ==========================================

// ------------------------------------------
// Tile — an icon and a name
// ------------------------------------------
export interface PlatformTileProps extends React.HTMLAttributes<HTMLElement> {
  icon: React.ReactNode;
  label: string;
  /** Render as a link. */
  href?: string;
  /** Swap the anchor for a framework Link. */
  linkComponent?: React.ElementType;
}

function Tile({ icon, label, href, linkComponent, className, ...props }: PlatformTileProps) {
  const Comp: React.ElementType = href ? (linkComponent ?? "a") : "div";
  return (
    <Comp
      data-tile=""
      {...(href ? { href } : {})}
      className={cn(
        "group relative flex aspect-square flex-col items-center justify-center gap-2.5 border-b border-r border-foreground/[0.08] px-2 text-center outline-none transition-colors duration-300 hover:bg-foreground/[0.03] focus-visible:bg-foreground/[0.03]",
        className,
      )}
      {...props}
    >
      <span className="grid h-6 w-6 place-items-center text-foreground/40 transition-all duration-300 ease-out [&>svg]:h-[18px] [&>svg]:w-[18px] group-hover:-translate-y-0.5 group-hover:scale-110 group-hover:text-primary group-focus-visible:text-primary">
        {icon}
      </span>
      <span className="text-[11px] font-medium leading-tight text-foreground/50 transition-colors duration-300 group-hover:text-foreground">
        {label}
      </span>
    </Comp>
  );
}

// ------------------------------------------
// Feature — a 2×2 tile with a tilting card
// ------------------------------------------
export interface PlatformFeatureProps extends React.HTMLAttributes<HTMLElement> {
  icon: React.ReactNode;
  label: string;
  href?: string;
  linkComponent?: React.ElementType;
  /** What sits on the card — see `PlatformGrid.Mock` for the frame. */
  children: React.ReactNode;
}

function Feature({ icon, label, href, linkComponent, className, children, ...props }: PlatformFeatureProps) {
  const Comp: React.ElementType = href ? (linkComponent ?? "a") : "div";
  return (
    <Comp
      data-tile=""
      {...(href ? { href } : {})}
      className={cn(
        "group relative col-span-2 row-span-2 flex aspect-square flex-col items-center justify-between border-b border-r border-foreground/[0.08] bg-gradient-to-b from-muted to-background px-2 pb-4 pt-6 outline-none transition-colors duration-300",
        className,
      )}
      {...props}
    >
      {/* The card leans until the pointer arrives, then straightens and tilts with it. */}
      <div className="flex w-full flex-1 items-center justify-center">
        <div className="w-[76%] max-w-[15rem] -rotate-[4deg] transition-transform duration-500 ease-out group-hover:rotate-0">
          <TiltedCard tiltIntensity={9} glareOpacity={0.12} scaleOnHover={1.03} className="h-auto">
            {children}
          </TiltedCard>
        </div>
      </div>
      <span className="flex items-center gap-2.5 text-[15px] font-semibold tracking-tight text-foreground">
        <span className="grid h-6 w-fit place-items-center [&>svg]:h-5 [&>svg]:w-5">{icon}</span>
        {label}
      </span>
    </Comp>
  );
}

// ------------------------------------------
// Mock and Pill — what goes on a feature's card
// ------------------------------------------
function Mock({ className, children, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        "space-y-1.5 rounded-xl border border-foreground/[0.08] bg-card p-3 text-left text-card-foreground",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
}

function Pill({
  tone = "ink",
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLSpanElement> & { tone?: "ink" | "accent" | "soft" }) {
  return (
    <span
      className={cn(
        "inline-flex shrink-0 items-center rounded-full px-1.5 py-[3px] text-[7.5px] font-semibold leading-none",
        tone === "ink" && "bg-foreground text-background",
        tone === "accent" && "bg-primary text-primary-foreground",
        tone === "soft" && "bg-foreground/[0.08] font-medium text-foreground/60",
        className,
      )}
      {...props}
    >
      {children}
    </span>
  );
}

// ------------------------------------------
// The reveal: each tile rises in after its own delay (`--tile-at`), with
// GSAP's power3.out as a CSS easing.
// ------------------------------------------
const EASE_OUT =
  "linear(0, .1945, .3591, .4971, .6115, .7052, .7808, .8409, .8877, .9233, .9497, .9686, .9816, .9901, .9952, .998, .9994, .9999, 1, 1)";

const REVEAL_CSS = `
@keyframes platform-tile-in { from { opacity: 0; transform: translateY(10px) scale(0.9); } }
[data-tile-reveal] [data-tile] { animation: platform-tile-in 0.7s ${EASE_OUT} var(--tile-at, 0s) backwards; }
`;

/**
 * Delays for a wave from the centre of a grid, `each` seconds apart: GSAP's
 * `stagger: { each, grid: "auto", from: "center" }`, step for step. The
 * column count is read from where the tiles sit — the first tile that is not
 * further right than the one before it starts the second row.
 */
function centreWave(tiles: HTMLElement[], each: number) {
  const l = tiles.length;
  if (!l) return [];
  let w = 0;
  let max = -Infinity;
  while (max < (max = tiles[w++].getBoundingClientRect().left) && w < l) {
    // walk along the first row
  }
  if (w < l) w--;
  const originX = Math.min(w, l) * 0.5 - 0.5;
  const originY = (l * 0.5) / w - 0.5;
  const d = tiles.map((_, j) => Math.hypot((j % w) - originX, originY - Math.floor(j / w)));
  const min = Math.min(...d);
  const range = Math.max(...d) - min;
  const total = each * (w > l ? l - 1 : Math.max(w, l / w));
  return d.map((dist) => Math.round((((dist - min) / range || 0) * total) * 1e7) / 1e7);
}

// ------------------------------------------
// Root
// ------------------------------------------
export interface PlatformGridProps extends React.HTMLAttributes<HTMLElement> {
  eyebrow?: React.ReactNode;
  heading: React.ReactNode;
  intro?: React.ReactNode;
  /** Accent for hovered icons, pills and the spotlight; defaults to the theme's primary. */
  accent?: string;
  /** Play the reveal when the section enters the viewport (default) or immediately. */
  reveal?: "in-view" | "immediate";
  /** Fade the outer columns, so the grid reads as a window onto something larger. */
  fadeEdges?: boolean;
  children: React.ReactNode;
}

export function PlatformGrid({
  eyebrow,
  heading,
  intro,
  accent,
  reveal = "in-view",
  fadeEdges = true,
  className,
  style,
  children,
  ...props
}: PlatformGridProps) {
  const sectionRef = useRef<HTMLElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);
  const [inView, setInView] = useState(reveal === "immediate");

  useEffect(() => {
    if (inView) return;
    const el = sectionRef.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          setInView(true);
          io.disconnect();
        }
      },
      { threshold: 0.15 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [inView]);

  // The reveal: every tile rises in, in a wave from the centre of the grid.
  // Tiles render opaque on the server; this only runs once the page is live.
  useEffect(() => {
    if (!inView) return;
    const grid = gridRef.current;
    if (!grid) return;
    const reduced =
      typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (reduced) return;
    const tiles = Array.from(grid.querySelectorAll<HTMLElement>("[data-tile]"));
    const delays = centreWave(tiles, 0.08);
    tiles.forEach((tile, i) => tile.style.setProperty("--tile-at", `${delays[i]}s`));
    // Written here rather than rendered, so it lands together with the start
    // times above and React never has to re-render to start the reveal.
    grid.setAttribute("data-tile-reveal", "");
  }, [inView]);

  // The spotlight is driven by CSS variables written straight to the grid, so
  // moving the pointer never re-renders the tiles.
  const onMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const el = e.currentTarget;
    const r = el.getBoundingClientRect();
    el.style.setProperty("--spot-x", `${e.clientX - r.left}px`);
    el.style.setProperty("--spot-y", `${e.clientY - r.top}px`);
    el.style.setProperty("--spot-on", "1");
  };
  const onLeave = (e: React.MouseEvent<HTMLDivElement>) => {
    e.currentTarget.style.setProperty("--spot-on", "0");
  };

  return (
    <section
      ref={sectionRef}
      className={cn("w-full bg-background text-foreground", className)}
      style={accent ? ({ ...style, "--primary": accent } as React.CSSProperties) : style}
      {...props}
    >
      {(eyebrow || heading || intro) && (
        <header className="mx-auto max-w-2xl px-6 pb-10 pt-14 text-center sm:pb-12 sm:pt-16">
          {eyebrow && (
            <p className="text-[13px] font-medium uppercase tracking-[0.12em] text-foreground/55">{eyebrow}</p>
          )}
          <h2 className="mt-3 font-sans text-[2rem] font-medium leading-[1.1] tracking-[-0.03em] sm:text-[2.5rem]">
            {heading}
          </h2>
          {intro && (
            <p className="mx-auto mt-4 max-w-[30rem] text-[15px] leading-[1.7] text-foreground/60">{intro}</p>
          )}
        </header>
      )}

      <div
        className={cn(
          "relative mx-auto max-w-[1180px]",
          fadeEdges &&
            "lg:[mask-image:linear-gradient(to_right,transparent,black_12%,black_88%,transparent)] lg:[-webkit-mask-image:linear-gradient(to_right,transparent,black_12%,black_88%,transparent)]",
        )}
      >
        <style>{REVEAL_CSS}</style>
        <div
          ref={gridRef}
          onMouseMove={onMove}
          onMouseLeave={onLeave}
          className="relative grid grid-cols-2 border-l border-t border-foreground/[0.08] [grid-auto-flow:dense] sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-8 xl:grid-cols-8"
        >
          {/* The spotlight: a soft disc of the accent under the pointer. */}
          <div
            aria-hidden
            className="pointer-events-none absolute inset-0 z-0 opacity-[var(--spot-on,0)] transition-opacity duration-500 motion-reduce:hidden"
            style={{
              background:
                "radial-gradient(240px circle at var(--spot-x, 50%) var(--spot-y, 50%), color-mix(in oklab, var(--primary) 9%, transparent), transparent 70%)",
            }}
          />
          {children}
        </div>
      </div>
    </section>
  );
}

PlatformGrid.Tile = Tile;
PlatformGrid.Feature = Feature;
PlatformGrid.Mock = Mock;
PlatformGrid.Pill = Pill;

export default PlatformGrid;

"use client";

import { cn } from "@/lib/utils";
import React, { useEffect, useRef } from "react";
import { createSpringFollower, type SpringFollower } from "./motion-curves";

export interface TiltedCardProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  tiltIntensity?: number; // Maximum rotation in degrees (e.g., 15)
  glareOpacity?: number; // Maximum opacity of the glare effect (0 to 1)
  scaleOnHover?: number; // Scale factor when hovered (e.g., 1.05)
}

// Pointer tilt: every frame the tilt chases the pointer through this spring,
// keeping its velocity when the pointer moves on — no animation library, just
// the spring's equation of motion stepped on requestAnimationFrame.
const TILT_SPRING = { damping: 25, stiffness: 300, mass: 0.5, restDelta: 0.001, restSpeed: 0.01 };
// Hover scale, same approach, so leaving mid-grow springs back from where it is.
const HOVER_SPRING = { stiffness: 300, damping: 20, mass: 1, restDelta: 0.005, restSpeed: 0.01 };

/** Maps -1..1 onto `from..to`, clamped at both ends. */
const mapRange = (v: number, from: number, to: number) => {
  const p = Math.min(Math.max((v + 1) / 2, 0), 1);
  return from + (to - from) * p;
};

const glareBackground = (x: number, y: number) =>
  `radial-gradient(circle at ${x}% ${y}%, var(--theme-color,var(--primary)), transparent 65%)`;

export const TiltedCard = React.forwardRef<HTMLDivElement, TiltedCardProps>(
  (
    {
      children,
      className,
      tiltIntensity = 15,
      glareOpacity = 0.2,
      scaleOnHover = 1.02,
      ...props
    },
    ref,
  ) => {
    const cardRef = useRef<HTMLDivElement>(null);
    const glareRef = useRef<HTMLDivElement>(null);

    React.useImperativeHandle(ref, () => cardRef.current as HTMLDivElement);

    // Read at paint time, so a changed prop applies from the next frame.
    const latest = useRef({ tiltIntensity, scaleOnHover });
    latest.current = { tiltIntensity, scaleOnHover };

    const springs = useRef<{
      x: SpringFollower;
      y: SpringFollower;
      scale: SpringFollower;
    } | null>(null);

    useEffect(() => {
      // Writes the card transform and the glare straight to the DOM, the way
      // motion values do — no React render per frame.
      const paint = () => {
        const s = springs.current;
        const card = cardRef.current;
        if (!s || !card) return;
        const tilt = latest.current.tiltIntensity;
        const x = s.x.get();
        const y = s.y.get();
        const scale = s.scale.get();
        const rotateX = mapRange(y, tilt, -tilt);
        const rotateY = mapRange(x, -tilt, tilt);
        const parts: string[] = [];
        if (scale !== 1) parts.push(`scale(${scale})`);
        if (rotateX !== 0) parts.push(`rotateX(${rotateX}deg)`);
        if (rotateY !== 0) parts.push(`rotateY(${rotateY}deg)`);
        card.style.transform = parts.length ? parts.join(" ") : "none";
        if (glareRef.current) {
          glareRef.current.style.background = glareBackground(
            mapRange(x, 0, 100),
            mapRange(y, 0, 100),
          );
        }
      };

      springs.current = {
        x: createSpringFollower(0, paint, TILT_SPRING),
        y: createSpringFollower(0, paint, TILT_SPRING),
        scale: createSpringFollower(1, paint, HOVER_SPRING),
      };

      return () => {
        springs.current?.x.destroy();
        springs.current?.y.destroy();
        springs.current?.scale.destroy();
        springs.current = null;
      };
    }, []);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
      if (!cardRef.current) return;
      const rect = cardRef.current.getBoundingClientRect();
      const x = (e.clientX - rect.left) / rect.width - 0.5;
      const y = (e.clientY - rect.top) / rect.height - 0.5;
      springs.current?.x.set(x * 2);
      springs.current?.y.set(y * 2);
    };

    const handleMouseLeave = () => {
      springs.current?.x.set(0);
      springs.current?.y.set(0);
    };

    // Hover scale follows a mouse or pen; a touch never counts as hovering.
    const handlePointerEnter = (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerType === "touch") return;
      springs.current?.scale.set(latest.current.scaleOnHover);
    };

    const handlePointerLeave = (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerType === "touch") return;
      springs.current?.scale.set(1);
    };

    return (
      <div
        className={cn("relative perspective-[1000px] w-full h-full", className)}
        {...props}
      >
        <div
          ref={cardRef}
          onMouseMove={handleMouseMove}
          onMouseLeave={handleMouseLeave}
          onPointerEnter={handlePointerEnter}
          onPointerLeave={handlePointerLeave}
          style={{
            transformStyle: "preserve-3d",
          }}
          className="relative w-full h-full rounded-2xl overflow-visible shadow-[0_10px_30px_rgba(0,0,0,0.08)] dark:shadow-[0_10px_30px_rgba(0,0,0,0.5)] transition-shadow duration-300 hover:shadow-[0_20px_40px_rgba(0,0,0,0.14)] dark:hover:shadow-[0_20px_40px_rgba(0,0,0,0.7)] group cursor-pointer"
        >
          <div
            className="relative w-full h-full z-10"
            style={
              {
                transform: "translateZ(30px)",
                "--glare-opacity": glareOpacity,
              } as React.CSSProperties
            }
          >
            {children}

            {/* Dynamic Theme Color Glare Overlay */}
            <div
              ref={glareRef}
              className="absolute inset-0 z-50 pointer-events-none opacity-0 group-hover:opacity-[var(--glare-opacity)] transition-opacity duration-300 rounded-2xl"
              style={{ background: glareBackground(50, 50) }}
            />
          </div>
        </div>
      </div>
    );
  },
);
TiltedCard.displayName = "TiltedCard";

/**
 * Motion curves with no animation library behind them.
 *
 * The components here ship as CSS, GSAP or Motion builds that must move
 * identically, so the curves are computed once, from the same numbers, and
 * handed to whichever engine runs them:
 *
 *   - `cubicBezier(x1, y1, x2, y2)` → an easing function (GSAP accepts any
 *     `(progress) => value` as `ease`), exact for Framer's `ease: [..]` arrays
 *     and for CSS `cubic-bezier()`.
 *   - `spring({ stiffness, damping, mass })` → the analytic solution Framer
 *     Motion uses, as an easing function plus the time it takes to settle, or
 *     as a CSS `linear()` string for a fixed start and end.
 *   - `createSpringFollower` → a value that chases a moving target through the
 *     same spring every frame, like Framer's `useSpring`, for pointer-driven
 *     motion that no fixed curve can describe.
 */

// ---------------------------------------------------------------------------
// Cubic bezier
// ---------------------------------------------------------------------------

/**
 * The CSS / Framer cubic-bezier as a function of progress. Newton-Raphson
 * with a bisection fallback, the same solver browsers use.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  if (x1 === y1 && x2 === y2) return (t: number) => t;

  const a = (p1: number, p2: number) => 1 - 3 * p2 + 3 * p1;
  const b = (p1: number, p2: number) => 3 * p2 - 6 * p1;
  const c = (p1: number) => 3 * p1;
  const at = (t: number, p1: number, p2: number) =>
    ((a(p1, p2) * t + b(p1, p2)) * t + c(p1)) * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * a(p1, p2) * t * t + 2 * b(p1, p2) * t + c(p1);

  const solveX = (x: number) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      const err = at(t, x1, x2) - x;
      if (Math.abs(err) < 1e-7) return t;
      t -= err / s;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 30 && hi - lo > 1e-7; i++) {
      const value = at(t, x1, x2);
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : at(solveX(x), y1, y2));
}

/** Motion's named eases, as the cubic-beziers they are. */
export const FRAMER_EASE = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
  circIn: [0.55, 0, 1, 0.45],
  circOut: [0.55, 0, 0.45, 1],
  circInOut: [0.85, 0, 0.15, 1],
  backIn: [0.31, 0.01, 0.66, -0.59],
  backOut: [0.33, 1.53, 0.69, 0.99],
  anticipate: [0.66, -0.56, 0.34, 1.35],
} as const;

/**
 * Motion's default layout transition (`layout` / `layoutId`):
 * `{ duration: 0.45, ease: [0.4, 0, 0.1, 1] }`.
 */
export const LAYOUT_TRANSITION = { duration: 0.45, ease: [0.4, 0, 0.1, 1] as const };

// ---------------------------------------------------------------------------
// Spring
// ---------------------------------------------------------------------------

export interface SpringOptions {
  /** Framer default 100. */
  stiffness?: number;
  /** Framer default 10. */
  damping?: number;
  /** Framer default 1. */
  mass?: number;
  /** Starting velocity, in units of the whole distance per second. */
  velocity?: number;
  /** How close to the end counts as settled, as a fraction of the distance. */
  restDelta?: number;
}

/**
 * Normalised position (0 → 1) of a spring released from 0 towards 1, at time
 * `t` seconds. The closed-form solution Motion's `spring()` generator
 * uses for the under-, critically and over-damped cases.
 */
export function springAt(options: SpringOptions = {}) {
  const { stiffness = 100, damping = 10, mass = 1, velocity = 0 } = options;
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  // Framer's convention: distance still to cover, velocity toward it negated.
  const delta = 1;
  const v0 = -velocity;

  if (zeta < 1) {
    const omegaD = omega0 * Math.sqrt(1 - zeta * zeta);
    return (t: number) => {
      const envelope = Math.exp(-zeta * omega0 * t);
      return (
        1 -
        envelope *
          (((v0 + zeta * omega0 * delta) / omegaD) * Math.sin(omegaD * t) +
            delta * Math.cos(omegaD * t))
      );
    };
  }
  if (zeta === 1) {
    return (t: number) => 1 - Math.exp(-omega0 * t) * (delta + (v0 + omega0 * delta) * t);
  }
  const omegaD = omega0 * Math.sqrt(zeta * zeta - 1);
  return (t: number) => {
    const envelope = Math.exp(-zeta * omega0 * t);
    const freq = Math.min(omegaD * t, 300);
    return (
      1 -
      (envelope *
        ((v0 + zeta * omega0 * delta) * Math.sinh(freq) + omegaD * delta * Math.cosh(freq))) /
        omegaD
    );
  };
}

/** Seconds until the spring stays within `restDelta` of its end. */
export function springDuration(options: SpringOptions = {}) {
  const at = springAt(options);
  const restDelta = options.restDelta ?? 0.001;
  const step = 1 / 240;
  let lastOutside = 0;
  for (let t = 0; t <= 10; t += step) {
    if (Math.abs(1 - at(t)) > restDelta) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.max(lastOutside + step, step);
}

/**
 * A spring as a duration and an easing function over it — what GSAP takes:
 *
 *   const { duration, ease } = springEase({ stiffness: 300, damping: 20 });
 *   gsap.to(el, { y: 0, duration, ease });
 *
 * Exact for a fixed start and end; a spring that has to react mid-flight to a
 * new target needs `createSpringFollower` instead.
 */
export function springEase(options: SpringOptions = {}) {
  const duration = springDuration(options);
  const at = springAt(options);
  return {
    duration,
    ease: (progress: number) => (progress >= 1 ? 1 : at(progress * duration)),
  };
}

/**
 * A spring as a CSS `linear()` easing and its duration in ms, for
 * `transition` / `animation` with a fixed start and end.
 *
 *   const { easing, duration } = springLinear({ stiffness: 400, damping: 30 });
 *   el.style.transition = `transform ${duration}ms ${easing}`;
 */
export function springLinear(options: SpringOptions = {}, pointsPerSecond = 60) {
  const duration = springDuration(options);
  const at = springAt(options);
  const count = Math.max(Math.ceil(duration * pointsPerSecond), 8);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const t = (i / count) * duration;
    points.push(String(Math.round((i === count ? 1 : at(t)) * 10000) / 10000));
  }
  return { easing: `linear(${points.join(", ")})`, duration: Math.round(duration * 1000) };
}

// ---------------------------------------------------------------------------
// Spring follower (useSpring equivalent)
// ---------------------------------------------------------------------------

/** Something that calls back once per frame with the time since the last, in ms. */
export interface FrameTicker {
  add: (callback: (deltaMs: number) => void) => () => void;
}

/** requestAnimationFrame as a ticker — the library-free default. */
export const rafTicker: FrameTicker = {
  add(callback) {
    let last = performance.now();
    let frame = requestAnimationFrame(function tick(now) {
      callback(now - last);
      last = now;
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  },
};

export interface SpringFollower {
  /** Chase a new target from wherever the value is now, keeping its velocity. */
  set: (target: number) => void;
  /** Move to a value instantly, with no motion. */
  jump: (value: number) => void;
  get: () => number;
  destroy: () => void;
}

/**
 * A value that follows its target through a spring, integrating the same
 * equation of motion Framer's `useSpring` solves — so a pointer-driven spring
 * reads the same in every build. Runs only while moving; `onUpdate` receives
 * each new value.
 */
export function createSpringFollower(
  initial: number,
  onUpdate: (value: number) => void,
  options: SpringOptions & { restSpeed?: number; ticker?: FrameTicker } = {},
): SpringFollower {
  const { stiffness = 100, damping = 10, mass = 1, ticker = rafTicker } = options;
  const restDelta = options.restDelta ?? 0.01;
  const restSpeed = options.restSpeed ?? 0.01;
  let value = initial;
  let target = initial;
  let velocity = 0;
  let stop: (() => void) | null = null;

  const step = (deltaMs: number) => {
    // Fixed 1ms sub-steps keep the integration stable for stiff springs and
    // independent of the frame rate.
    const steps = Math.min(Math.max(Math.round(deltaMs), 1), 250);
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity;
      velocity += (force / mass) * 0.001;
      value += velocity * 0.001;
    }
    if (Math.abs(target - value) < restDelta && Math.abs(velocity) < restSpeed) {
      value = target;
      velocity = 0;
      stop?.();
      stop = null;
    }
    onUpdate(value);
  };

  return {
    set(next) {
      target = next;
      if (!stop && value !== target) stop = ticker.add(step);
    },
    jump(next) {
      stop?.();
      stop = null;
      value = target = next;
      velocity = 0;
      onUpdate(value);
    },
    get: () => value,
    destroy() {
      stop?.();
      stop = null;
    },
  };
}
